import{_ as i,o as n,c as t,a0 as a}from"./chunks/framework.BXmxXpv-.js";const h=JSON.parse('{"title":"Research Directions","description":"Research directions of the Intelligent Computing Systems Laboratory at UESTC, spanning edge intelligence, embodied sensing, swarm communication, and intelligent information processing.","frontmatter":{"title":"Research Directions","description":"Research directions of the Intelligent Computing Systems Laboratory at UESTC, spanning edge intelligence, embodied sensing, swarm communication, and intelligent information processing."},"headers":[],"relativePath":"research.md","filePath":"en/research.md","lastUpdated":1789370207000}'),o={name:"research.md"};function r(s,e,l,c,d,m){return n(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="research-directions" tabindex="-1">Research Directions <a class="header-anchor" href="#research-directions" aria-label="Permalink to &quot;Research Directions&quot;">​</a></h1><p>The Intelligent Computing Systems Laboratory studies how intelligent computing systems sense, communicate, and act in the physical world. Our work connects computing architectures, wireless systems, intelligent sensing, and data-driven methods across four research directions.</p><h2 id="iot-edge-architecture-and-intelligent-computing" tabindex="-1">IoT Edge Architecture and Intelligent Computing <a class="header-anchor" href="#iot-edge-architecture-and-intelligent-computing" aria-label="Permalink to &quot;IoT Edge Architecture and Intelligent Computing&quot;">​</a></h2><p>We investigate lightweight edge-intelligence algorithms and chip design for embodied intelligent systems, edge-cloud collaborative computing architectures, task-offloading strategies, mobile analytics, and machine-learning applications at the edge.</p><h2 id="embodied-intelligent-sensing-and-interaction" tabindex="-1">Embodied Intelligent Sensing and Interaction <a class="header-anchor" href="#embodied-intelligent-sensing-and-interaction" aria-label="Permalink to &quot;Embodied Intelligent Sensing and Interaction&quot;">​</a></h2><p>We explore intelligent perception of the physical world, cognitive mechanisms for image and visual information computing, and passive wireless sensing systems that connect physical signals with intelligent interaction.</p><h2 id="swarm-collaborative-intelligence-and-communication" tabindex="-1">Swarm Collaborative Intelligence and Communication <a class="header-anchor" href="#swarm-collaborative-intelligence-and-communication" aria-label="Permalink to &quot;Swarm Collaborative Intelligence and Communication&quot;">​</a></h2><p>We study communication technologies for swarm collaboration, distributed intelligence and collaborative decision-making, wireless systems, and network security.</p><h2 id="intelligent-information-processing-and-applications" tabindex="-1">Intelligent Information Processing and Applications <a class="header-anchor" href="#intelligent-information-processing-and-applications" aria-label="Permalink to &quot;Intelligent Information Processing and Applications&quot;">​</a></h2><p>We develop methods for data mining, recommendation systems, and intelligent data analysis, together with prototype systems and application demonstrations.</p><h2 id="related-information" tabindex="-1">Related Information <a class="header-anchor" href="#related-information" aria-label="Permalink to &quot;Related Information&quot;">​</a></h2><ul><li><a href="/projects">Representative research projects</a></li><li><a href="/publication">Selected publications</a></li><li><a href="/people">Laboratory members</a></li><li><a href="/contact">Contact us</a></li></ul>',12)])])}const p=i(o,[["render",r]]);export{h as __pageData,p as default};
